"use strict";(globalThis.webpackChunkgrc||=[]).push([[75824],{10740(e){e.exports=JSON.parse('{"citeKey":"sun2003gridharvest","slug":"sun-2003-grid-harvest-cb4e","title":"Grid Harvest Service: A System for Long-Term, Application-Level Task Scheduling","authors":["X.-H. Sun","M. Wu"],"venue":"The 2003 IEEE International Parallel and Distributed Processing Symposium (IPDPS 2003), Nice, France","type":"Conference","entryType":"inproceedings","date":"April, 2003","year":2003,"era":"iit","month":4,"doi":"10.1109/ipdps.2003.1213102","abstract":"With the emergence of grid computing environment, performance measurement, analysis and prediction of non-dedicated distributed systems have become increasingly important. In this study, we put forward a novel performance model for non-dedicated network computing. Based on this model, a performance prediction and task scheduling system called Grid Harvest Service (GHS), has been designed and implemented. GHS consists of a performance measurement component, a prediction component and a scheduling component. Different scheduling algorithms are proposed for different situations. Experimental results show that the GHS system provides satisfactory solution for performance prediction and scheduling of large applications and that GHS has a real potential. Keywords: performance prediction and measurement, task scheduling, resources sharing, grid computing, performance modeling","hasAbstract":true,"lede":"With the emergence of grid computing environment, performance measurement, analysis and prediction of non-dedicated distributed systems have become increasingly important.","links":{"pdf":"https://grc.iit.edu/papers/2003/sun-2003-grid-harvest-cb4e.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);